import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * How the customer list is narrowed down.
 *
 * <p>A customer matches when it satisfies both parts:
 *
 * <ul>
 * <li>{@code name} is split on whitespace into terms, and every term must occur
 * as a substring of the first or the last name. Case and accents are ignored in
 * both directions, so {@code makinen} matches {@code Mäkinen} just as
 * {@code mäkinen} does. Blank text matches every customer.
 * <li>{@code statuses} keeps only customers in one of the given statuses. An
 * empty set matches every customer.
 * </ul>
 *
 * <p>The filter belongs to the backend: {@link CustomerRepository} applies it
 * before paging, so a filtered grid still fetches one page at a time.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** The filter that matches every customer. */
    public static CustomerFilter empty() {
        return EMPTY;
    }

    /** Whether this filter lets every customer through. */
    public boolean isEmpty() {
        return terms().isEmpty() && statuses.isEmpty();
    }

    /** Whether the given customer passes both parts of this filter. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        List<String> terms = terms();
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        return terms.stream()
                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    /** The name filter as normalized search terms; empty when nothing was typed. */
    public List<String> terms() {
        String normalized = normalize(name);
        return normalized.isEmpty() ? List.of() : List.of(WHITESPACE.split(normalized));
    }

    /**
     * Lower-cases, strips accents and collapses whitespace, so that comparing two
     * normalized strings ignores case and accents on both sides.
     */
    private static String normalize(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        String withoutAccents = COMBINING_MARKS.matcher(decomposed).replaceAll("");
        return WHITESPACE.matcher(withoutAccents.toLowerCase(Locale.ROOT).strip()).replaceAll(" ");
    }
}
